/* From Uiverse.io by Iliasman2 - Tags: button */
.__UIV_SCOPE__ .designer-btn {
  display: inline-block;
  padding: 14px 40px;
  font-size: 20px;
  font-weight: bold;
  text-align: center;
  border-radius: 30px;
  cursor: pointer;
  border: 2px solid black;
  transition: all 0.3s ease;
  background: linear-gradient(to bottom, #b2b5b3, #a5a7a6);
  color: rgb(57, 53, 53);
}

.__UIV_SCOPE__ .designer-btn:hover {
  border: 2px solid rgb(109, 107, 107);
  color: #a5a7a6;
  box-shadow: 0 5px #666;
  transform: translateY(-5px);
  background: linear-gradient(to bottom, #2e2f2e, #323433);
}

.__UIV_SCOPE__ .designer-btn:focus,
.__UIV_SCOPE__ .designer-btn:active {
  transform: translateY(4px);
}
